async function onClick(e){const nav=e.target.closest('[data-tab]');if(nav)return navigate(nav.dataset.tab);const b=e.target.closest('[data-act]');if(!b)return;const a=b.dataset.act,id=b.dataset.id;
 try{
 if(a==='logout'){await sb.auth.signOut();return}
 if(a==='oauthgoogle'||a==='oauthfacebook'){const provider=a==='oauthgoogle'?'google':'facebook';const redirectTo=location.origin+location.pathname;const {error}=await sb.auth.signInWithOAuth({provider,options:{redirectTo}});if(error)throw error;return}
 if(a==='templateproduct')return downloadText(productTemplate,'ken-products-template.csv');if(a==='templatemetrics')return downloadText(metricsTemplate,'ken-metrics-template.csv');
 if(a==='inspect'){selectedProduct='inspect:'+id;tab='hunter';navigate('hunter');return}if(a==='closeinspect'){selectedProduct=null;render();return}
 if(a==='reviewproduct'){const p=state.products.find(x=>x.id===id);if(!p)throw Error('ไม่พบสินค้า');if(!p.sourceUrl||!p.observedAt||!p.productUrl&&!p.affiliateUrl)throw Error('กรุณามีลิงก์แหล่งข้อมูล เวลาต้นทาง และ URL สินค้าก่อนรับรอง');if(!confirm(`ยืนยันว่าได้เปิดต้นทางและตรวจข้อมูลจริงของสินค้า: ${p.name} ?\nระบบไม่ได้ยืนยันข้อมูลแทน API`))return;p.reviewedAt=new Date().toISOString();p.reviewedBy=currentUser?.id||'local_operator';commit('product_review',`${p.platform} / ${p.productId} ตรวจโดยผู้ใช้`);showAlert('บันทึกการตรวจแล้ว (ไม่ใช่ API verified)');return}
 if(a==='deleteproduct'){const p=state.products.find(x=>x.id===id);if(!p||!confirm(`ลบ ${p.name} ออกจากคลัง?`))return;state.products=state.products.filter(x=>x.id!==id);commit('product_delete',`${p.platform}/${p.productId}`);return}
 if(a==='useproduct'){const p=state.products.find(x=>x.id===id);if(!p)throw Error('ไม่พบสินค้า');if(!canCampaign(p))throw Error('สินค้าไม่ผ่าน Data Gate');selectedProduct=p.id;return navigate('autopilot')}
 if(a==='deletechar'){const c=state.characters.find(x=>x.id===id);if(!c||!confirm(`ลบตัวละคร ${c.name}?`))return;state.characters=state.characters.filter(x=>x.id!==id);if(c.storagePath&&sb){const {error}=await sb.storage.from('character-assets').remove([c.storagePath]);if(error)showAlert('ลบโปรไฟล์แล้ว แต่ลบรูปจาก Storage ไม่สำเร็จ',true)}commit('character_delete',c.name);return}
 if(a==='characterprompt'){const c=state.characters.find(x=>x.id===id);if(c){await navigator.clipboard.writeText(characterPrompt(c));showAlert('คัดลอก Master Prompt แล้ว')}return}
 if(a==='viewcampaign'){selectedCampaign=id;render();return}if(a==='backcampaign'){selectedCampaign=null;render();return}
 if(a==='deletecampaign'){const c=getCampaign(id);if(!c||!confirm(`ลบแคมเปญ ${c.productName}?`))return;state.campaigns=state.campaigns.filter(x=>x.id!==id);commit('campaign_delete',c.productName);return}
 if(a==='renderwebm'){const c=getCampaign(b.dataset.c),o=c?.outputs.find(x=>x.id===b.dataset.o);if(!c||!o)throw Error('ไม่พบคลิป');return await renderWebm(c,o)}
 if(a==='copyscript'||a==='copyprompt'){const c=getCampaign(b.dataset.c),o=c?.outputs.find(x=>x.id===b.dataset.o);if(!c||!o)throw Error('ไม่พบคลิป');await navigator.clipboard.writeText(a==='copyscript'?o.script:videoPrompt(c,o));showAlert('คัดลอกเรียบร้อย');return}
 if(a==='backup'){downloadText(JSON.stringify(state,null,2),`ken-affiliate-backup-${todayBangkok()}.json`,'application/json');return}
 if(a==='clearworkspace'){if(!confirm('ล้างข้อมูลสินค้า ตัวละคร สถิติ และแคมเปญทั้งหมด?'))return;if(!confirm('ยืนยันอีกครั้งว่าต้องการล้างพื้นที่งานทั้งหมด'))return;state=EMPTY();commit('workspace_reset','ล้างข้อมูลทั้งหมด');return}
 }catch(err){showAlert(err.message,true)}
}
async function onChange(e){const input=e.target;if(input.id==='productsFile'||input.id==='metricsFile'){const file=input.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('CSV ต้องไม่เกิน 5 MB');const content=await file.text();const digest=await crypto.subtle.digest('SHA-256',await file.arrayBuffer());const sha256=Array.from(new Uint8Array(digest)).map(x=>x.toString(16).padStart(2,'0')).join('');if(input.id==='productsFile'){
 const result=importProducts(content,{fileName:file.name});result.products.forEach(p=>p.importSha256=sha256);report.products={accepted:result.products.length,total:result.total,errors:result.errors};state.products=mergeByKey(state.products,result.products,x=>x.sourceKey);audit('products_import',`${file.name}: นำเข้า ${result.products.length}, ปฏิเสธ ${result.errors.length} แถว`);persist();render();showAlert(`นำเข้า ${result.products.length} สินค้า · รอตรวจหลักฐาน`);
 }else{const r=importMetrics(content,{fileName:file.name});r.metrics.forEach(m=>m.importSha256=sha256);report.metrics={accepted:r.metrics.length,total:r.total,errors:r.errors};state.metrics=mergeByKey(state.metrics,r.metrics,x=>`${x.platform}:${x.postUrl}:${x.observedAt}`);audit('metrics_import',`${file.name}: นำเข้า ${r.metrics.length}, ปฏิเสธ ${r.errors.length} แถว`);persist();render();showAlert(`นำเข้า ${r.metrics.length} Metric records`)}
 }catch(err){showAlert(err.message,true)}return}
 if(input.id==='backupInput'){const file=input.files?.[0];if(!file)return;try{const data=normalizeState(JSON.parse(await file.text()));if(!confirm('นำเข้าไฟล์ Backup จะเขียนทับข้อมูลปัจจุบัน ยืนยันหรือไม่?'))return;state=data;commit('backup_restore',`Import backup ${file.name}`);showAlert('กู้คืนข้อมูลแล้ว')}catch(err){showAlert(err.message,true)}}
}
async function onSubmit(e){e.preventDefault();const form=e.target;try{
 if(form.id==='magicForm'){const email=safeText(new FormData(form).get('email')),redirectTo=location.origin+location.pathname;const {error}=await sb.auth.signInWithOtp({email,options:{emailRedirectTo:redirectTo}});if(error)throw error;showAlert('ตรวจอีเมลเพื่อรับ Magic Link');return}
 if(form.id==='manualProductForm'){const fd=new FormData(form),entry=Object.fromEntries(fd.entries());if(!entry.commission_rate&&!entry.commission_amount)throw Error('กรุณาใส่อัตราคอมมิชชันหรือคอมมิชชันต่อชิ้นจากข้อมูลจริง');const observed=new Date(entry.observed_at);if(Number.isNaN(observed.valueOf()))throw Error('เวลาของข้อมูลไม่ถูกต้อง');const values={product_id:entry.product_id,name:entry.name,platform:entry.platform,price:entry.price,commission_rate:entry.commission_rate,commission_amount:entry.commission_amount,product_url:entry.product_url,affiliate_url:entry.affiliate_url,source_url:entry.source_url,observed_at:observed.toISOString()};const fields=Object.keys(values);const output=importProducts(exportCSV([values],fields),{fileName:'manual-entry'});if(output.errors.length||!output.products.length)throw Error('ข้อมูลสินค้ายังไม่ถูกต้อง');output.products[0].sourceKind='manual_entered';state.products=mergeByKey(state.products,output.products,x=>x.sourceKey);commit('product_manual_entry',`${entry.platform} / ${entry.product_id} รอตรวจโดยผู้ใช้`);showAlert('เพิ่มสินค้าแล้ว กรุณาตรวจหลักฐานในหน้าสินค้า');return}
 if(form.id==='characterForm')return await addCharacter(form);
 if(form.id==='pilotForm'){
  const fd=new FormData(form);if(!fd.get('confirm'))throw Error('ต้องยืนยันเงื่อนไขการตรวจคลิป');const p=state.products.find(x=>x.id===fd.get('productId')),c=state.characters.find(x=>x.id===fd.get('characterId'));if(!p||!c)throw Error('กรุณาเลือกสินค้าและตัวละคร');const platforms=fd.getAll('platform');if(!platforms.length)throw Error('เลือกแพลตฟอร์มอย่างน้อยหนึ่งรายการ');const opts={quantity:Number(fd.get('quantity')),startDate:fd.get('startDate'),spacingDays:Number(fd.get('spacing')),platforms,budgetTHB:Number(fd.get('budget'))};const newC=createCampaign(p,c,opts);state.campaigns.push(newC);state.settings={...state.settings,platforms,campaignClips:opts.quantity,spacingDays:opts.spacingDays,budgetTHB:opts.budgetTHB};selectedCampaign=newC.id;tab='campaigns';const u=new URL(location.href);u.searchParams.set('tab',tab);history.replaceState({},'',u);commit('campaign_create',`${p.platform} / ${p.productId} · ${c.name} · ${newC.outputs.length} drafts`);showAlert('สร้างแคมเปญแบบร่างเรียบร้อย');return}
 }catch(err){showAlert(err.message,true)}}
document.addEventListener('click',onClick);document.addEventListener('change',onChange);document.addEventListener('submit',onSubmit);initialize();